// Test: Epic Default Priority
// Verifies that Epic issue types get the same default priority (P2/MEDIUM) as other issue types

use bead_forge::model::{Issue, IssueType, Priority};
use chrono::Utc;

#[test]
fn test_epic_default_priority_is_p2_medium() {
    // Create an Epic issue using default priority
    let epic = Issue {
        id: "bf-test-epic".to_string(),
        title: "Test Epic".to_string(),
        issue_type: IssueType::Epic,
        created_at: Utc::now(),
        updated_at: Utc::now(),
        ..Default::default()
    };

    // Verify epic gets P2 (MEDIUM) default priority, not P0 or any other special priority
    assert_eq!(epic.priority, Priority::MEDIUM);
    assert_eq!(epic.priority, Priority(2));
    assert_eq!(epic.priority.0, 2);
}

#[test]
fn test_all_issue_types_share_default_priority() {
    // All issue types should have the same default priority (P2/MEDIUM)
    let types = vec![
        IssueType::Task,
        IssueType::Bug,
        IssueType::Feature,
        IssueType::Epic,
        IssueType::Chore,
        IssueType::Docs,
        IssueType::Question,
    ];

    for issue_type in types {
        let issue = Issue {
            id: format!("bf-test-{:?}", issue_type).to_lowercase().replace("\"", ""),
            title: format!("Test {:?}", issue_type),
            issue_type: issue_type.clone(),
            created_at: Utc::now(),
            updated_at: Utc::now(),
            ..Default::default()
        };

        assert_eq!(
            issue.priority,
            Priority::MEDIUM,
            "Issue type {:?} should have P2 default priority",
            issue_type
        );
    }
}

#[test]
fn test_default_priority_not_p0() {
    // Verify that the default priority is NOT P0 (CRITICAL)
    let default: Priority = Default::default();
    assert_ne!(default, Priority::CRITICAL);
    assert_ne!(default, Priority(0));
    assert_eq!(default, Priority::MEDIUM);
}

#[test]
fn test_default_priority_not_p1() {
    // Verify that the default priority is NOT P1 (HIGH)
    let default: Priority = Default::default();
    assert_ne!(default, Priority::HIGH);
    assert_ne!(default, Priority(1));
    assert_eq!(default, Priority::MEDIUM);
}

#[test]
fn test_epic_serialization_with_default_priority() {
    // Test that Epic with default priority serializes correctly
    let epic = Issue {
        id: "bf-epic".to_string(),
        title: "Epic Issue".to_string(),
        issue_type: IssueType::Epic,
        created_at: Utc::now(),
        updated_at: Utc::now(),
        ..Default::default()
    };

    let json = serde_json::to_string(&epic).unwrap();

    // Verify JSON contains "priority":2 (P2/MEDIUM)
    assert!(json.contains(r#""priority":2"#));
    assert!(json.contains(r#""issue_type":"epic""#));

    // Deserialize and verify
    let deserialized: Issue = serde_json::from_str(&json).unwrap();
    assert_eq!(deserialized.issue_type, IssueType::Epic);
    assert_eq!(deserialized.priority, Priority::MEDIUM);
}

